import React, { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { FiUserPlus } from "react-icons/fi";
import DashboardLayout from "../../layouts/DashboardLayout";
import Card from "../../components/Card";
import FormField from "../../components/FormField";
import Loading from "../../components/Loading";
import { instructorApi } from "../../api/instructorApi";
import { departmentApi } from "../../api/departmentApi";
import { useLookupOptions } from "../../hooks/useLookupOptions";
import { useToast } from "../../context/ToastContext";
import { extractErrorMessage } from "../../api/axios";
import { validateFields, isRequired, isEmail, isPhone } from "../../utils/validators";

const initialValues = { first_name: "", last_name: "", email: "", phone: "", department_id: "" };

export default function InstructorForm() {
  const { id } = useParams();
  const isEditMode = Boolean(id);
  const navigate = useNavigate();
  const toast = useToast();

  const [values, setValues] = useState(initialValues);
  const [errors, setErrors] = useState({});
  const [isLoading, setIsLoading] = useState(isEditMode);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { options: departmentOptions } = useLookupOptions(
    departmentApi.getAll,
    (d) => ({ value: d.id, label: d.name })
  );

  useEffect(() => {
    if (!isEditMode) return;
    instructorApi
      .getOne(id)
      .then(({ data }) => {
        const i = data?.data || data;
        setValues({
          first_name: i.first_name || "",
          last_name: i.last_name || "",
          email: i.email || "",
          phone: i.phone || "",
          department_id: i.department_id || ""
        });
      })
      .catch((err) => toast.error(extractErrorMessage(err, "Unable to load this instructor.")))
      .finally(() => setIsLoading(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  function handleChange(e) {
    const { name, value } = e.target;
    setValues((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => ({ ...prev, [name]: "" }));
  }

  async function handleSubmit(e) {
    e.preventDefault();
    const fieldErrors = validateFields(values, {
      first_name: [isRequired],
      last_name: [isRequired],
      email: [isRequired, isEmail],
      phone: [isRequired, isPhone],
      department_id: [isRequired]
    });
    if (Object.keys(fieldErrors).length > 0) {
      setErrors(fieldErrors);
      return;
    }

    setIsSubmitting(true);
    try {
      if (isEditMode) {
        await instructorApi.update(id, values);
        toast.success("Instructor updated successfully");
      } else {
        await instructorApi.create(values);
        toast.success("Instructor created successfully");
      }
      navigate("/instructors");
    } catch (err) {
      toast.error(extractErrorMessage(err, "Unable to save this instructor."));
    } finally {
      setIsSubmitting(false);
    }
  }

  if (isLoading) {
    return (
      <DashboardLayout>
        <Loading label="Loading instructor..." />
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      <div className="max-w-lg mx-auto">
        <div className="flex items-center gap-2 mb-6">
          <div className="h-9 w-9 rounded-lg bg-navy-100 text-navy-700 flex items-center justify-center">
            <FiUserPlus size={16} />
          </div>
          <h1 className="font-display text-xl text-navy-800">
            {isEditMode ? "Edit Instructor" : "Add Instructor"}
          </h1>
        </div>

        <Card className="p-6">
          <form onSubmit={handleSubmit} className="space-y-4" noValidate>
            <div className="grid sm:grid-cols-2 gap-4">
              <FormField
                label="First Name"
                name="first_name"
                value={values.first_name}
                onChange={handleChange}
                error={errors.first_name}
                required
              />
              <FormField
                label="Last Name"
                name="last_name"
                value={values.last_name}
                onChange={handleChange}
                error={errors.last_name}
                required
              />
            </div>
            <FormField
              label="Email"
              name="email"
              type="email"
              value={values.email}
              onChange={handleChange}
              error={errors.email}
              required
              placeholder="instructor@university.edu"
            />
            <FormField
              label="Phone"
              name="phone"
              value={values.phone}
              onChange={handleChange}
              error={errors.phone}
              required
              placeholder="+251 9xx xxx xxx"
            />
            <FormField
              as="select"
              label="Department"
              name="department_id"
              value={values.department_id}
              onChange={handleChange}
              error={errors.department_id}
              required
              options={departmentOptions}
              placeholder="Select department"
            />
            <div className="flex gap-3 pt-2">
              <button
                type="button"
                onClick={() => navigate("/instructors")}
                className="flex-1 py-2.5 rounded-lg text-sm border border-line text-ink hover:bg-paper transition"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={isSubmitting}
                className="flex-1 py-2.5 rounded-lg text-sm bg-navy-700 text-white hover:bg-navy-800 transition disabled:opacity-60"
              >
                {isSubmitting ? "Saving..." : isEditMode ? "Save Changes" : "Create Instructor"}
              </button>
            </div>
          </form>
        </Card>
      </div>
    </DashboardLayout>
  );
}
